const LESSONS = {"en":{"foundations":{"title":"Stock Market Foundations","level":"beginner","time":"6 lessons","summary":"What a share is, how exchanges work, and how an order becomes a trade."},"investing":{"title":"Investing & Wealth Building","level":"beginner","time":"8 lessons","summary":"Set goals, understand your time horizon, diversify, and let compounding work over years."},"sip-mutual-funds":{"title":"SIP & Mutual Funds","level":"beginner","time":"7 lessons","summary":"How a Systematic Investment Plan works, what NAV means, and how to read fund costs."},"reading-charts":{"title":"Reading Charts","level":"beginner","time":"6 lessons","summary":"Understand line, bar and candlestick charts, OHLC data, and volume."},"fundamental-analysis":{"title":"Fundamental Analysis","level":"intermediate","time":"9 lessons","summary":"Evaluate a business using its financial statements, key ratios and quality checks."},"technical-analysis":{"title":"Technical Analysis","level":"intermediate","time":"10 lessons","summary":"Study price and volume patterns, trends, support, resistance and common indicators.","sections":[{"h":"Trend","p":"An uptrend makes higher highs and higher lows. A downtrend makes lower highs and lower lows. Trading in the direction of the trend is a common starting principle, but trends can reverse."},{"h":"Support and resistance","p":"Support is a price zone where buying has tended to appear. Resistance is a zone where selling has tended to appear. If price breaks above resistance on strong volume, that level can later act as support."},{"h":"Moving averages","p":"A moving average smooths price over a set number of periods. A 50-period simple moving average is common for medium-term trend. Price above the average is often read as bullish and below it as bearish. A short average crossing a long one is a widely watched signal."},{"h":"RSI and MACD","ul":["RSI (14) measures momentum on a 0 to 100 scale. Readings above 70 are often called overbought and below 30 oversold, but strong trends can stay there for a long time.","MACD compares two moving averages. The MACD line crossing its signal line is a common momentum signal."]},{"h":"Limits of technical analysis","p":"Indicators lag and can give false signals. Use them together with risk rules, and never rely on a single indicator."}]},"swing-trading":{"title":"Swing Trading","level":"intermediate","time":"8 lessons","summary":"Hold trades for days to weeks using clear setups, entry and exit rules, and a trade journal."},"risk-management":{"title":"Risk Management","level":"intermediate","time":"7 lessons","summary":"Protect your capital with position sizing, stop losses, exposure limits and a drawdown plan."},"intraday-trading":{"title":"Intraday Trading","level":"advanced","time":"9 lessons","summary":"Trade within one session. Understand liquidity, order execution, margin and the real risks."},"futures-options":{"title":"Futures & Options","level":"advanced","time":"12 lessons","summary":"Understand futures, call and put options, strike price, expiry, margin and payoff, along with their risks."},"option-greeks":{"title":"Option Greeks & Strategies","level":"advanced","time":"10 lessons","summary":"Measure how option prices respond to price, time and volatility, and build defined-risk strategies."},"trading-psychology":{"title":"Trading Psychology","level":"advanced","time":"6 lessons","summary":"Recognise biases such as fear, greed and overtrading, and build a disciplined process."},"candlestick-patterns":{"title":"Candlestick and Chart Patterns","level":"intermediate","time":"25 patterns","summary":"Learn what each candle and chart shape signals, when it matters, how to confirm it, and the mistake to avoid."},"technical-indicators":{"title":"Technical Indicators","level":"intermediate","time":"10 indicators","summary":"Understand what moving averages, RSI, MACD, volume and other indicators measure, when to use each one, and how to use them in a trade."},"tax-basics":{"title":"Tax Basics for Indian Investors and Traders","level":"intermediate","time":"11 topics","summary":"How gains from shares, mutual funds, intraday and F&O are taxed in India, what records to keep, and where to verify the current rules."},"balance-sheet":{"title":"How to Read a Balance Sheet","level":"intermediate","time":"13 topics","summary":"What a balance sheet shows, how to read assets, liabilities and equity, and the ratios that reveal financial strength."},"cash-flow-statement":{"title":"How to Read a Cash Flow Statement","level":"intermediate","time":"13 topics","summary":"Where a company's real cash comes from and goes, and why cash flow can tell you more than profit."},"quarterly-results":{"title":"How to Read Quarterly Results","level":"intermediate","time":"13 topics","summary":"How to read the numbers in a quarterly results filing, compare them correctly, and spot one-off items."},"annual-report":{"title":"How to Read an Annual Report","level":"intermediate","time":"13 topics","summary":"The parts of a company's annual report, what each section tells you, and the warning signs to look for."},"shareholding-pattern":{"title":"Shareholding Pattern and Promoter Holding","level":"intermediate","time":"12 topics","summary":"Who owns a company, how promoter, institutional and public holdings change, and what pledged shares mean."},"valuation-basics":{"title":"Valuation Basics: What Is a Share Worth?","level":"advanced","time":"8 topics","summary":"P/E, P/B, EV/EBITDA, PEG and discounted cash flow explained, with their limits and how to combine them."},"corporate-actions":{"title":"Corporate Actions: Dividends, Bonus, Splits, Rights and Buybacks","level":"intermediate","time":"13 topics","summary":"What companies do with shares and cash, how each action changes the price and your holding, and how to avoid confusion on the ex-date."},"market-rules":{"title":"Market Rules & Investor Protection","level":"beginner","time":"10 topics","summary":"Market timings, settlement, price bands and circuit breakers, applying for IPOs, spotting scams and tips, and how to complain if something goes wrong."}},"hi":{"foundations":{"title":"शेयर बाज़ार की मूल बातें","level":"beginner","time":"6 पाठ","summary":"शेयर क्या है, एक्सचेंज कैसे काम करते हैं, और ऑर्डर ट्रेड में कैसे बदलता है।"},"investing":{"title":"निवेश और धन निर्माण","level":"beginner","time":"8 पाठ","summary":"लक्ष्य तय करें, समय-सीमा समझें, विविधीकरण करें और चक्रवृद्धि को वर्षों तक काम करने दें।"},"sip-mutual-funds":{"title":"SIP और म्यूचुअल फंड","level":"beginner","time":"7 पाठ","summary":"SIP कैसे काम करता है, NAV का मतलब क्या है, और फंड की लागत कैसे पढ़ें।"},"reading-charts":{"title":"चार्ट कैसे पढ़ें","level":"beginner","time":"6 पाठ","summary":"लाइन, बार और कैंडलस्टिक चार्ट, OHLC डेटा और वॉल्यूम समझें।"},"fundamental-analysis":{"title":"फंडामेंटल एनालिसिस","level":"intermediate","time":"9 पाठ","summary":"वित्तीय विवरण, प्रमुख अनुपात और गुणवत्ता जाँच से किसी कारोबार का मूल्यांकन करें।"},"technical-analysis":{"title":"टेक्निकल एनालिसिस","level":"intermediate","time":"10 पाठ","summary":"कीमत और वॉल्यूम पैटर्न, ट्रेंड, सपोर्ट, रेज़िस्टेंस और आम इंडिकेटर पढ़ें।","sections":[{"h":"ट्रेंड","p":"अपट्रेंड में ऊँचे हाई और ऊँचे लो बनते हैं। डाउनट्रेंड में नीचे हाई और नीचे लो बनते हैं। ट्रेंड की दिशा में ट्रेड करना एक आम शुरुआती सिद्धांत है, लेकिन ट्रेंड पलट भी सकते हैं।"},{"h":"सपोर्ट और रेज़िस्टेंस","p":"सपोर्ट वह कीमत-क्षेत्र है जहाँ अक्सर ख़रीदारी दिखी है। रेज़िस्टेंस वह क्षेत्र है जहाँ बिक्री का दबाव रहा है। मज़बूत वॉल्यूम के साथ रेज़िस्टेंस टूटे तो वही स्तर बाद में सपोर्ट बन सकता है।"},{"h":"मूविंग एवरेज","p":"मूविंग एवरेज किसी तय अवधि की औसत कीमत है, जो चाल को सुचारु बनाता है। मध्यम-अवधि के ट्रेंड के लिए 50-अवधि का सिंपल मूविंग एवरेज आम है। कीमत औसत से ऊपर हो तो अक्सर तेज़ी और नीचे हो तो मंदी माना जाता है। छोटे एवरेज का बड़े को पार करना व्यापक रूप से देखा जाने वाला संकेत है।"},{"h":"RSI और MACD","ul":["RSI (14) 0 से 100 के पैमाने पर मोमेंटम मापता है। 70 से ऊपर को अक्सर ओवरबॉट और 30 से नीचे को ओवरसोल्ड कहा जाता है, पर मज़बूत ट्रेंड इन स्तरों पर लंबे समय तक रह सकते हैं।","MACD दो मूविंग एवरेज की तुलना करता है। MACD लाइन का सिग्नल लाइन को पार करना एक आम मोमेंटम संकेत है।"]},{"h":"टेक्निकल एनालिसिस की सीमाएँ","p":"इंडिकेटर देर से संकेत देते हैं और गलत संकेत भी दे सकते हैं। इन्हें जोखिम नियमों के साथ इस्तेमाल करें, और किसी एक इंडिकेटर पर भरोसा न करें।"}]},"swing-trading":{"title":"स्विंग ट्रेडिंग","level":"intermediate","time":"8 पाठ","summary":"साफ़ सेटअप, एंट्री-एग्ज़िट नियम और ट्रेड जर्नल से कुछ दिनों से कुछ हफ़्तों तक ट्रेड रखें।"},"risk-management":{"title":"जोखिम प्रबंधन","level":"intermediate","time":"7 पाठ","summary":"पोज़िशन साइज़, स्टॉप लॉस, एक्सपोज़र सीमा और ड्रॉडाउन योजना से पूँजी की रक्षा करें।"},"intraday-trading":{"title":"इंट्राडे ट्रेडिंग","level":"advanced","time":"9 पाठ","summary":"एक ही सत्र में ट्रेड करें। लिक्विडिटी, ऑर्डर निष्पादन, मार्जिन और असली जोखिम समझें।"},"futures-options":{"title":"फ्यूचर्स और ऑप्शंस (F&O)","level":"advanced","time":"12 पाठ","summary":"फ्यूचर्स, कॉल और पुट ऑप्शंस, स्ट्राइक, एक्सपायरी, मार्जिन और पेऑफ़ को उनके जोखिमों के साथ समझें।"},"option-greeks":{"title":"ऑप्शन ग्रीक्स और रणनीतियाँ","level":"advanced","time":"10 पाठ","summary":"कीमत, समय और अस्थिरता के साथ ऑप्शन की कीमत कैसे बदलती है, यह समझें और सीमित-जोखिम रणनीतियाँ बनाएँ।"},"trading-psychology":{"title":"ट्रेडिंग मनोविज्ञान","level":"advanced","time":"6 पाठ","summary":"डर, लालच और ओवरट्रेडिंग जैसे पूर्वाग्रह पहचानें और अनुशासित प्रक्रिया बनाएँ।"},"candlestick-patterns":{"title":"कैंडलस्टिक और चार्ट पैटर्न","level":"intermediate","time":"25 पैटर्न","summary":"हर कैंडल और चार्ट आकार का संकेत, उसका महत्व, पुष्टि कैसे करें, और कौन सी गलती से बचें, यह सीखें।"},"technical-indicators":{"title":"टेक्निकल इंडिकेटर","level":"intermediate","time":"10 इंडिकेटर","summary":"मूविंग एवरेज, RSI, MACD, वॉल्यूम और अन्य इंडिकेटर क्या मापते हैं, हर एक कब इस्तेमाल करें, और ट्रेड में कैसे इस्तेमाल करें, यह समझें।"},"tax-basics":{"title":"भारतीय निवेशकों और ट्रेडरों के लिए टैक्स बेसिक्स","level":"intermediate","time":"11 विषय","summary":"भारत में शेयर, म्यूचुअल फंड, इंट्राडे और F&O से होने वाले लाभ पर टैक्स कैसे लगता है, कौन से रिकॉर्ड रखें, और मौजूदा नियम कहाँ जाँचें।"},"balance-sheet":{"title":"बैलेंस शीट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"बैलेंस शीट क्या दिखाती है, संपत्ति, देनदारी और इक्विटी कैसे पढ़ें, और वित्तीय मज़बूती बताने वाले अनुपात।"},"cash-flow-statement":{"title":"कैश फ़्लो स्टेटमेंट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी का असली नकद कहाँ से आता और कहाँ जाता है, और कैश फ़्लो मुनाफ़े से ज़्यादा क्या बताता है।"},"quarterly-results":{"title":"तिमाही नतीजे कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"तिमाही नतीजों के आँकड़े कैसे पढ़ें, सही तुलना कैसे करें, और एक-बार की मदों को कैसे पहचानें।"},"annual-report":{"title":"सालाना रिपोर्ट कैसे पढ़ें","level":"intermediate","time":"13 विषय","summary":"कंपनी की सालाना रिपोर्ट के हिस्से, हर हिस्सा क्या बताता है, और चेतावनी के संकेत।"},"shareholding-pattern":{"title":"शेयरहोल्डिंग पैटर्न और प्रमोटर होल्डिंग","level":"intermediate","time":"12 विषय","summary":"कंपनी का मालिक कौन है, प्रमोटर, संस्थागत और सार्वजनिक होल्डिंग कैसे बदलती है, और गिरवी शेयरों का क्या मतलब है।"},"valuation-basics":{"title":"वैल्यूएशन की मूल बातें: शेयर की क़ीमत क्या होनी चाहिए?","level":"advanced","time":"8 विषय","summary":"P/E, P/B, EV/EBITDA, PEG और डिस्काउंटेड कैश फ़्लो समझाए गए, उनकी सीमाओं के साथ और उन्हें मिलाकर कैसे इस्तेमाल करें।"},"corporate-actions":{"title":"कॉर्पोरेट एक्शन: डिविडेंड, बोनस, स्प्लिट, राइट्स और बायबैक","level":"intermediate","time":"13 विषय","summary":"कंपनियाँ शेयर और नकद के साथ क्या करती हैं, हर एक्शन कीमत और आपकी होल्डिंग को कैसे बदलता है, और एक्स-डेट पर भ्रम से कैसे बचें।"},"market-rules":{"title":"बाज़ार के नियम और निवेशक सुरक्षा","level":"beginner","time":"10 विषय","summary":"बाज़ार का समय, सेटलमेंट, प्राइस बैंड और सर्किट ब्रेकर, IPO में आवेदन, धोखाधड़ी और टिप्स पहचानना, और कुछ गलत होने पर शिकायत कैसे करें।"}}};
const LESSON_OVERRIDES = {"en":{"technical-analysis":{"sections":[{"h":"1. What technical analysis studies","p":"Technical analysis studies price and volume to understand the behaviour of buyers and sellers. It assumes that price already reflects known information, and that patterns of behaviour tend to repeat because people react in similar ways to similar situations. It is a method for managing probabilities and timing, not a guarantee of future prices."},{"h":"2. Trend: the first thing to identify","p":"A trend is the general direction of price. Uptrend: higher highs and higher lows. Downtrend: lower highs and lower lows. Sideways: no clear direction. Most beginners lose money by trading against the trend. Identify the trend on a higher timeframe first, and then look for entries in that direction.","ul":["Trend lines connect swing lows in an uptrend and swing highs in a downtrend.","A trend is weakening when a new high fails to form, or when price breaks its last swing low.","Moving averages can confirm trend direction: price above a rising average suggests an uptrend."]},{"h":"3. Support and resistance","p":"Support is a price area where buying has tended to appear. Resistance is an area where selling has tended to appear. They are zones, not exact prices. A level becomes stronger each time price respects it, and when price breaks through with volume, the broken resistance often becomes new support."},{"h":"4. Moving averages","p":"A moving average is the average price over a set number of periods. It smooths noise and shows direction. The most used are 20, 50 and 200 periods. A simple moving average (SMA) weights all periods equally; an exponential moving average (EMA) gives more weight to recent prices and reacts faster.","p2":"Example: the 5-period SMA of closes 100, 102, 104, 103 and 105 is 102.8. On the next day, with a close of 107, the average becomes 104.2, because 100 drops out and 107 comes in."},{"h":"5. Momentum: RSI and MACD","p":"Momentum indicators measure how fast price is moving and whether that speed is changing.","ul":["RSI (relative strength index): a 0 to 100 scale over 14 periods. Above 70 is often overbought, below 30 oversold. In strong trends it can stay in those zones for a long time.","MACD: the difference between a 12-period and a 26-period EMA, with a 9-period signal line. A MACD line crossing above its signal line is a bullish momentum signal.","Divergence: price makes a new high while RSI or MACD makes a lower high. It warns that momentum is fading."]},{"h":"6. Volume: the strength behind the move","p":"Volume confirms price moves. A breakout on high volume is more reliable than one on low volume. A rally on falling volume is weak. High volume at the end of a long fall can mark exhaustion, but confirm with the next candles before acting."},{"h":"7. Chart patterns and breakouts","p":"Chart patterns such as triangles, flags and head and shoulders describe a range that price is building. The breakout from the range is the trade signal. Measure the potential move from the pattern's height only as a rough guide, and place a stop just inside the range, so a failed breakout exits quickly."},{"h":"8. Risk first: stops and position size","p":"Technical signals are only as good as the risk attached to them. Decide the stop-loss before the entry, based on structure (below the last swing low) or volatility (for example 2 times ATR). Then size the position so that the loss at the stop equals your planned risk, such as 1% of capital.","p2":"Example: capital ₹1,00,000, risk 1% = ₹1,000. Entry ₹250, stop ₹240 (₹10 risk per share). Position = 1,000 ÷ 10 = 100 shares. If the stop is hit, the loss is about ₹1,000, before costs."},{"h":"9. Combining tools without overloading the chart","p":"Pick one tool from each group: a trend tool (moving averages), a momentum tool (RSI or MACD), and volume. Add structure (support, resistance, trend lines). That is enough for most decisions. Adding many indicators that all measure momentum repeats the same information. Use the chart as a checklist: trend agrees, momentum agrees, volume agrees, and the level is clear."},{"h":"10. Common mistakes and how to avoid them","ul":["Using hindsight to draw levels after the move.","Changing indicator settings until the chart looks right.","Trading without a stop because the setup looks strong.","Averaging down into a losing trade against the trend.","Testing on too few trades to know whether the method works. Track at least 30 to 50 trades."]}]}},"hi":{"technical-analysis":{"sections":[{"h":"1. टेक्निकल एनालिसिस क्या अध्ययन करता है","p":"टेक्निकल एनालिसिस कीमत और वॉल्यूम का अध्ययन करता है ताकि ख़रीदारों और विक्रेताओं के व्यवहार को समझा जा सके। यह मानता है कि कीमत में पहले से ज्ञात जानकारी झलकती है, और व्यवहार के पैटर्न दोहराते हैं क्योंकि लोग मिलती-जुलती स्थितियों पर मिलती-जुलती प्रतिक्रिया देते हैं। यह संभावनाएँ और समय संभालने का तरीका है, भविष्य की कीमतों की गारंटी नहीं।"},{"h":"2. ट्रेंड: सबसे पहले पहचानें","p":"ट्रेंड कीमत की सामान्य दिशा है। अपट्रेंड: ऊँचे हाई और ऊँचे लो। डाउनट्रेंड: नीचे हाई और नीचे लो। साइडवे: कोई साफ़ दिशा नहीं। कई शुरुआती ट्रेंड के ख़िलाफ़ ट्रेड करके पैसा खोते हैं। पहले ऊँची समय-सीमा पर ट्रेंड पहचानें, फिर उसी दिशा में एंट्री खोजें।","ul":["अपट्रेंड में स्विंग लो और डाउनट्रेंड में स्विंग हाई को ट्रेंड लाइन जोड़ती है।","ट्रेंड कमज़ोर होता है जब नया हाई न बने, या कीमत पिछला स्विंग लो तोड़े।","मूविंग एवरेज ट्रेंड की दिशा की पुष्टि कर सकते हैं: बढ़ते एवरेज के ऊपर कीमत अपट्रेंड का संकेत।"]},{"h":"3. सपोर्ट और रेज़िस्टेंस","p":"सपोर्ट वह कीमत-क्षेत्र है जहाँ ख़रीदारी दिखी है। रेज़िस्टेंस वह क्षेत्र है जहाँ बिकवाली दिखी है। ये ज़ोन हैं, सटीक कीमतें नहीं। हर बार कीमत का उसका सम्मान करने पर स्तर मज़बूत होता है, और वॉल्यूम के साथ कीमत उसे तोड़े तो टूटा हुआ रेज़िस्टेंस अक्सर नया सपोर्ट बनता है।"},{"h":"4. मूविंग एवरेज","p":"मूविंग एवरेज तय अवधियों का औसत कीमत है। यह शोर कम करता है और दिशा दिखाता है। सबसे ज़्यादा इस्तेमाल होने वाले 20, 50 और 200 अवधि के हैं। सिंपल मूविंग एवरेज (SMA) सभी अवधियों को बराबर वज़न देता है; एक्सपोनेंशियल (EMA) हाल की कीमतों को ज़्यादा वज़न देता है और तेज़ी से प्रतिक्रिया देता है।","p2":"उदाहरण: क्लोज़ 100, 102, 104, 103 और 105 का 5-अवधि SMA 102.8 है। अगले दिन क्लोज़ 107 है, तो औसत 104.2 हो जाता है, क्योंकि 100 बाहर और 107 अंदर।"},{"h":"5. मोमेंटम: RSI और MACD","p":"मोमेंटम इंडिकेटर मापते हैं कि कीमत कितनी तेज़ चल रही है और क्या वह गति बदल रही है।","ul":["RSI (रिलेटिव स्ट्रेंथ इंडेक्स): 14 अवधि पर 0 से 100 का पैमाना। 70 से ऊपर अक्सर ओवरबॉट, 30 से नीचे ओवरसोल्ड। मज़बूत ट्रेंड में ये स्तर लंबे समय तक रह सकते हैं।","MACD: 12 और 26 अवधि के EMA का अंतर, 9 अवधि की सिग्नल रेखा के साथ। MACD रेखा का सिग्नल रेखा को ऊपर पार करना तेज़ी का मोमेंटम संकेत।","डाइवर्जेंस: कीमत नया हाई बनाए पर RSI या MACD नीचा हाई। यह चेतावनी है कि मोमेंटम घट रहा है।"]},{"h":"6. वॉल्यूम: चाल के पीछे की ताकत","p":"वॉल्यूम कीमत की चाल की पुष्टि करता है। ज़्यादा वॉल्यूम पर ब्रेकआउट कम वॉल्यूम वाले से ज़्यादा भरोसेमंद है। घटते वॉल्यूम पर तेज़ी कमज़ोर है। लंबी गिरावट के अंत में ज़्यादा वॉल्यूम थकान का संकेत हो सकता है, पर कार्रवाई से पहले अगली कैंडल से पुष्टि करें।"},{"h":"7. चार्ट पैटर्न और ब्रेकआउट","p":"ट्राएंगल, फ़्लैग और हेड एंड शोल्डर्स जैसे चार्ट पैटर्न वह रेंज दिखाते हैं जो कीमत बना रही है। रेंज से ब्रेकआउट ट्रेड का संकेत है। संभावित चाल को पैटर्न की ऊँचाई से केवल मोटे अनुमान के रूप में मापें, और स्टॉप रेंज के ठीक अंदर रखें, ताकि विफल ब्रेकआउट से जल्दी बाहर निकलें।"},{"h":"8. पहले जोखिम: स्टॉप और पोज़िशन साइज़","p":"टेक्निकल संकेत उतने ही अच्छे हैं जितना उनके साथ जुड़ा जोखिम। एंट्री से पहले स्टॉप-लॉस तय करें, या तो स्ट्रक्चर पर (पिछले स्विंग लो के नीचे) या अस्थिरता पर (जैसे 2 गुना ATR)। फिर पोज़िशन का आकार ऐसा रखें कि स्टॉप पर नुकसान आपके तय जोखिम, जैसे पूँजी का 1%, के बराबर हो।","p2":"उदाहरण: पूँजी ₹1,00,000, जोखिम 1% = ₹1,000। एंट्री ₹250, स्टॉप ₹240 (प्रति शेयर ₹10 जोखिम)। पोज़िशन = 1,000 ÷ 10 = 100 शेयर। स्टॉप लगे तो नुकसान लगभग ₹1,000, शुल्क से पहले।"},{"h":"9. चार्ट को भरे बिना टूल जोड़ना","p":"हर समूह से एक टूल चुनें: एक ट्रेंड टूल (मूविंग एवरेज), एक मोमेंटम टूल (RSI या MACD), और वॉल्यूम। साथ में संरचना जोड़ें (सपोर्ट, रेज़िस्टेंस, ट्रेंड लाइन)। ज़्यादातर फ़ैसलों के लिए यही काफ़ी है। सभी मोमेंटम इंडिकेटर जोड़ने से वही जानकारी दोहराती है। चार्ट को चेकलिस्ट की तरह देखें: ट्रेंड सहमत, मोमेंटम सहमत, वॉल्यूम सहमत, और स्तर साफ़।"},{"h":"10. आम गलतियाँ और उनसे बचाव","ul":["चाल के बाद स्तर खींचने के लिए पिछली जानकारी का उपयोग।","चार्ट सही दिखे इसके लिए इंडिकेटर सेटिंग बदलते रहना।","मज़बूत सेटअप लगने पर बिना स्टॉप के ट्रेड।","ट्रेंड के ख़िलाफ़ घाटे वाले ट्रेड में औसत बढ़ाना।","यह जानने के लिए बहुत कम ट्रेड पर परखना कि तरीका काम करता है या नहीं। कम से कम 30 से 50 ट्रेड दर्ज करें।"]}]}}};
const LESSON_EXTRAS_EN = {"technical-analysis":{"examples":[{"title":"Five-period simple moving average","text":"Closes: 100, 102, 104, 103, 105. Average = 514 ÷ 5 = 102.8. Next day closes at 107 and the oldest value (100) drops out. New average = (102 + 104 + 103 + 105 + 107) ÷ 5 = 521 ÷ 5 = 104.2."},{"title":"RSI calculation","text":"Over 14 periods, average gain is 1.5 and average loss is 0.5. RS = 1.5 ÷ 0.5 = 3. RSI = 100 − 100 ÷ (1 + 3) = 75, which is above the common 70 overbought reference."}],"scenarios":[{"title":"Breakout on low volume","text":"Price moves above resistance, but volume is below average. Many such breakouts fail and return into the range. Waiting for a retest or higher volume reduces false signals."},{"title":"RSI overbought in a strong uptrend","text":"RSI reads 78 while the price keeps making higher highs. Strong trends can stay overbought for weeks. Selling only because RSI is above 70 often means missing the trend."},{"title":"Golden cross after a long decline","text":"The 50-day average crosses above the 200-day average after months of falling prices. This is widely watched, but it lags. Confirm with price structure and volume."}],"useCases":["Screening for stocks trading above their 200-day average.","Placing a stop loss just below a recent support level.","Timing an entry on a pullback to a moving average within an uptrend."],"takeaways":["Indicators are derived from price and volume; they describe, they do not predict with certainty.","Moving averages smooth noise and show trend direction.","RSI above 70 or below 30 signals extremes, but strong trends can persist.","Confirm signals with volume and price structure."],"practice":[{"q":"What is the 3-period simple moving average of 10, 12 and 14?","a":"(10 + 12 + 14) ÷ 3 = 12."},{"q":"An RSI reading of 25 is what kind of signal?","a":"An oversold reading. It suggests selling pressure may be exhausted, but it is not a guaranteed reversal."},{"q":"The MACD line crosses above its signal line. What does this suggest?","a":"Momentum is shifting upward. It is a bullish momentum signal, not a guarantee of a rise."}]}};
const LESSON_EXTRAS_HI = {"technical-analysis":{"examples":[{"title":"पाँच-अवधि का सिंपल मूविंग एवरेज","text":"क्लोज़: 100, 102, 104, 103, 105। औसत = 514 ÷ 5 = 102.8। अगले दिन क्लोज़ 107 है और पुराना मान (100) हट जाता है। नया औसत = (102 + 104 + 103 + 105 + 107) ÷ 5 = 521 ÷ 5 = 104.2।"},{"title":"RSI की गणना","text":"14 अवधियों में औसत लाभ 1.5 और औसत नुकसान 0.5 है। RS = 1.5 ÷ 0.5 = 3। RSI = 100 − 100 ÷ (1 + 3) = 75, जो आम ओवरबॉट स्तर 70 से ऊपर है।"}],"scenarios":[{"title":"कम वॉल्यूम पर ब्रेकआउट","text":"कीमत रेज़िस्टेंस के ऊपर जाती है, पर वॉल्यूम औसत से कम है। ऐसे कई ब्रेकआउट विफल होते हैं और कीमत वापस रेंज में आ जाती है। रीटेस्ट या ज़्यादा वॉल्यूम का इंतज़ार करने से झूठे संकेत कम होते हैं।"},{"title":"मज़बूत अपट्रेंड में RSI ओवरबॉट","text":"RSI 78 दिखाता है, जबकि कीमत लगातार ऊँचे हाई बना रही है। मज़बूत ट्रेंड हफ़्तों तक ओवरबॉट रह सकते हैं। केवल RSI 70 से ऊपर होने पर बेचने से अक्सर ट्रेंड छूट जाता है।"},{"title":"लंबी गिरावट के बाद गोल्डन क्रॉस","text":"महीनों की गिरावट के बाद 50-दिन का एवरेज 200-दिन के एवरेज को ऊपर पार करता है। इस पर व्यापक नज़र रहती है, पर यह देर से संकेत देता है। कीमत की संरचना और वॉल्यूम से पुष्टि करें।"}],"useCases":["उन शेयरों को स्क्रीन करना जो 200-दिन के एवरेज से ऊपर ट्रेड कर रहे हैं।","हाल के सपोर्ट के ठीक नीचे स्टॉप लॉस लगाना।","अपट्रेंड में मूविंग एवरेज तक पुलबैक पर एंट्री का समय तय करना।"],"takeaways":["इंडिकेटर कीमत और वॉल्यूम से बनते हैं; वे स्थिति बताते हैं, निश्चित भविष्यवाणी नहीं करते।","मूविंग एवरेज शोर कम करते हैं और ट्रेंड की दिशा दिखाते हैं।","RSI 70 से ऊपर या 30 से नीचे चरम स्थिति बताता है, पर मज़बूत ट्रेंड टिक सकते हैं।","संकेतों की पुष्टि वॉल्यूम और कीमत की संरचना से करें।"],"practice":[{"q":"10, 12 और 14 का 3-अवधि सिंपल मूविंग एवरेज क्या है?","a":"(10 + 12 + 14) ÷ 3 = 12।"},{"q":"RSI 25 का क्या संकेत है?","a":"ओवरसोल्ड स्तर। इसका मतलब बिकवाली का दबाव थक सकता है, पर पलटाव की गारंटी नहीं।"},{"q":"MACD लाइन उसकी सिग्नल लाइन को ऊपर पार करती है। इसका क्या मतलब है?","a":"मोमेंटम ऊपर की ओर बदल रहा है। यह तेज़ी का मोमेंटम संकेत है, पर बढ़त की गारंटी नहीं।"}]}};
